"use client";

import { useState } from "react";
import Link from "next/link";
import {
  ArrowLeft,
  FileCheck,
  Briefcase,
  ShieldCheck,
  Clock,
  CheckCircle2,
  AlertCircle,
  ,
  ,
   } from "lucide-react";

import { AnimatedPage } from "@/components/ui/AnimatedPage";
import { Button } from "@/components/ui/button";

const mockJobApplications = [
  {
    id: "app-101",
    jobTitle: "Bilingual Supervisor (Thai-Burmese)",
    company: "Mahachai Seafood Co., Ltd.",
    appliedDate: "Jul 28, 2026",
    status: "Interview Scheduled",
    statusType: "success", // pending, success, in_review
    note: "Interview scheduled on Aug 5, 2026 at 10:00 AM." },
  {
    id: "app-102",
    jobTitle: "Warehouse Staff & Logistics Helper",
    company: "Bangkok Express Logistics",
    appliedDate: "Jul 20, 2026",
    status: "Under Review",
    statusType: "in_review",
    note: "Application submitted and received by HR team." },
];

const mockVisaRequests = [
  {
    id: "req-201",
    serviceName: "Online 90-Day Report Assistance",
    submittedDate: "Jul 25, 2026",
    status: "Completed",
    statusType: "success",
    note: "Receipt generated and approved by Thai Immigration." },
  {
    id: "req-202",
    serviceName: "MOU Work Permit Extension Renewal",
    submittedDate: "Jul 15, 2026",
    status: "Processing Documents",
    statusType: "in_review",
    note: "Document verification in progress at Department of Employment." },
];

export default function ApplicationsPage() {
  const [activeTab, setActiveTab] = useState<"jobs" | "visa">("jobs");

  return (
    <AnimatedPage>
      <div className="min-h-screen bg-background py-8">
        <div className="container mx-auto px-6 max-w-5xl space-y-6">
          <Link
            href="/dashboard"
            className="inline-flex items-center text-xs text-muted-foreground hover:text-primary transition-colors"
          >
            <ArrowLeft className="mr-1.5 h-3.5 w-3.5" /> Back to Dashboard
          </Link>

          {/* Header Banner */}
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-border/60 pb-6">
            <div>
              <div className="flex items-center gap-2">
                <div className="flex h-10 w-10 items-center justify-center rounded-2xl bg-primary/10 text-primary">
                  <FileCheck className="h-5 w-5" />
                </div>
                <h1 className="text-2xl font-black text-foreground">My Applications & Requests</h1>
              </div>
              <p className="mt-1 text-xs text-muted-foreground">
                Track your job application progress, interview schedules, and submitted visa
                requests.
              </p>
            </div>
          </div>

          {/* Filter Tabs */}
          <div className="flex gap-2 border-b border-border/60 pb-3">
            <button
              type="button"
              onClick={() => setActiveTab("jobs")}
              className={`flex items-center gap-1.5 rounded-full px-4 py-2 text-xs font-bold transition-all ${
                activeTab === "jobs"
                  ? "bg-primary text-primary-foreground shadow-sm"
                  : "bg-muted/40 text-muted-foreground hover:bg-muted hover:text-foreground"
              }`}
            >
              <Briefcase className="h-3.5 w-3.5" /> Job Applications ({mockJobApplications.length})
            </button>

            <button
              type="button"
              onClick={() => setActiveTab("visa")}
              className={`flex items-center gap-1.5 rounded-full px-4 py-2 text-xs font-bold transition-all ${
                activeTab === "visa"
                  ? "bg-primary text-primary-foreground shadow-sm"
                  : "bg-muted/40 text-muted-foreground hover:bg-muted hover:text-foreground"
              }`}
            >
              <ShieldCheck className="h-3.5 w-3.5" /> Visa & Legal Requests (
              {mockVisaRequests.length})
            </button>
          </div>

          {/* Applications List */}
          <div className="space-y-4 pt-2">
            {/* Jobs Tab */}
            {activeTab === "jobs" &&
              (mockJobApplications.length > 0 ? (
                <div className="space-y-3">
                  {mockJobApplications.map((app) => (
                    <div
                      key={app.id}
                      className="rounded-3xl border border-border/80 bg-card p-5 shadow-sm space-y-3"
                    >
                      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-border/40 pb-3">
                        <div>
                          <h3 className="text-base font-bold text-foreground">{app.jobTitle}</h3>
                          <p className="text-xs text-muted-foreground">{app.company}</p>
                        </div>
                        <StatusBadge type={app.statusType} text={app.status} />
                      </div>

                      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 text-xs text-muted-foreground">
                        <div className="flex items-center gap-1.5">
                          <Clock className="h-3.5 w-3.5 text-primary shrink-0" />
                          <span>
                            Applied on:{" "}
                            <strong className="text-foreground">{app.appliedDate}</strong>
                          </span>
                        </div>
                        <p className="text-xs italic bg-muted/30 px-3 py-1.5 rounded-xl border border-border/40 text-foreground">
                          {app.note}
                        </p>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <EmptyState
                  label="No job applications submitted yet."
                  href="/jobs"
                  buttonText="Find Jobs"
                />
              ))}

            {/* Visa Requests Tab */}
            {activeTab === "visa" &&
              (mockVisaRequests.length > 0 ? (
                <div className="space-y-3">
                  {mockVisaRequests.map((req) => (
                    <div
                      key={req.id}
                      className="rounded-3xl border border-border/80 bg-card p-5 shadow-sm space-y-3"
                    >
                      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-border/40 pb-3">
                        <div>
                          <h3 className="text-base font-bold text-foreground">{req.serviceName}</h3>
                          <p className="text-xs text-muted-foreground">Request ID: {req.id}</p>
                        </div>
                        <StatusBadge type={req.statusType} text={req.status} />
                      </div>

                      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 text-xs text-muted-foreground">
                        <div className="flex items-center gap-1.5">
                          <Clock className="h-3.5 w-3.5 text-amber-500 shrink-0" />
                          <span>
                            Submitted on:{" "}
                            <strong className="text-foreground">{req.submittedDate}</strong>
                          </span>
                        </div>
                        <p className="text-xs italic bg-muted/30 px-3 py-1.5 rounded-xl border border-border/40 text-foreground">
                          {req.note}
                        </p>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <EmptyState
                  label="No visa or legal requests found."
                  href="/visa"
                  buttonText="Explore Visa Help"
                />
              ))}
          </div>
        </div>
      </div>
    </AnimatedPage>
  );
}

function StatusBadge({ type, text }: { type: string; text: string }) {
  if (type === "success") {
    return (
      <span className="inline-flex items-center gap-1 rounded-full bg-emerald-500/10 border border-emerald-500/20 px-3 py-1 text-xs font-bold text-emerald-600 self-start sm:self-auto">
        <CheckCircle2 className="h-3.5 w-3.5" /> {text}
      </span>
    );
  }
  return (
    <span className="inline-flex items-center gap-1 rounded-full bg-amber-500/10 border border-amber-500/20 px-3 py-1 text-xs font-bold text-amber-600 self-start sm:self-auto">
      <AlertCircle className="h-3.5 w-3.5" /> {text}
    </span>
  );
}

function EmptyState({
  label,
  href,
  buttonText }: {
  label: string;
  href: string;
  buttonText: string;
}) {
  return (
    <div className="rounded-3xl border border-border/80 bg-card p-10 text-center space-y-3">
      <FileCheck className="mx-auto h-10 w-10 text-muted-foreground" />
      <p className="text-xs text-muted-foreground">{label}</p>
      <Link href={href} className="inline-block">
        <Button size="sm" className="rounded-xl text-xs font-semibold">
          {buttonText}
        </Button>
      </Link>
    </div>
  );
}

"use client";

import { useState } from "react";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import {
  LayoutDashboard,
  User,
  Settings,
  Bookmark,
  FileCheck,
  Bot,
  LogOut,
  Briefcase,
  Building2,
  ShieldCheck,
  Plane,
  Banknote,
  Store,
  Calendar,
  Menu,
  X,
  ArrowLeft,
} from "lucide-react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";

// กลุ่มเมนูการจัดการบัญชีผู้ใช้
const userNavItems = [
  { href: "/dashboard", label: "Dashboard", icon: LayoutDashboard },
  { href: "/applications", label: "My Applications", icon: FileCheck },
  { href: "/saved", label: "Saved Items", icon: Bookmark },
  { href: "/profile", label: "My Profile", icon: User },
  { href: "/settings", label: "Settings", icon: Settings },
];

// กลุ่มเมนูบริการทั้งหมด (Explore All Services)
const serviceNavItems = [
  { href: "/jobs", label: "Jobs & Careers", icon: Briefcase, color: "text-blue-500" },
  { href: "/housing", label: "Housing & Rooms", icon: Building2, color: "text-emerald-500" },
  { href: "/visa", label: "Visa & Legal Help", icon: ShieldCheck, color: "text-amber-500" },
  { href: "/travel", label: "Travel & Flights", icon: Plane, color: "text-sky-500" },
  { href: "/money", label: "Money Services", icon: Banknote, color: "text-rose-500" },
  { href: "/directory", label: "Local Businesses", icon: Store, color: "text-purple-500" },
  { href: "/events", label: "Community Events", icon: Calendar, color: "text-indigo-500" },
  { href: "/ai", label: "Ask Mingalar AI", icon: Bot, color: "text-primary" },
];

export default function ProtectedLayout({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();
  const router = useRouter();
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isLoggingOut, setIsLoggingOut] = useState(false);

  // ฟังก์ชัน Log Out
  const handleLogout = async () => {
    try {
      setIsLoggingOut(true);
      const res = await fetch("/api/auth/logout", { method: "POST" });
      if (res.ok) {
        toast.success("Logged out successfully");
        router.push("/login");
        router.refresh();
      } else {
        router.push("/login");
      }
    } catch (error) {
      toast.error("Logout failed, redirecting...");
      router.push("/login");
    } finally {
      setIsLoggingOut(false);
    }
  };

  return (
    <div className="min-h-screen bg-muted/20 flex flex-col md:flex-row">
      {/* Mobile Header */}
      <div className="md:hidden sticky top-0 z-50 flex h-16 items-center justify-between border-b border-border/80 bg-background px-4 shadow-sm">
        <Link href="/dashboard" className="flex items-center gap-2 font-black text-lg text-primary">
          <span className="flex h-8 w-8 items-center justify-center rounded-xl bg-primary text-primary-foreground shadow-sm">
            M
          </span>
          <span>Mingalar BKK</span>
        </Link>
        <Button
          variant="ghost"
          size="sm"
          onClick={() => setSidebarOpen(!sidebarOpen)}
          className="p-2"
        >
          {sidebarOpen ? <X className="h-6 w-6" /> : <Menu className="h-6 w-6" />}
        </Button>
      </div>

      {/* Sidebar Navigation */}
      <aside
        className={`fixed inset-y-0 left-0 z-40 w-64 border-r border-border/80 bg-card p-4 transition-transform duration-300 md:static md:translate-x-0 flex flex-col justify-between ${
          sidebarOpen ? "translate-x-0" : "-translate-x-full"
        }`}
      >
        <div className="space-y-6">
          {/* Brand Logo Section */}
          <div className="hidden md:flex items-center gap-2 font-black text-xl text-primary px-2 py-1">
            <span className="flex h-9 w-9 items-center justify-center rounded-2xl bg-primary text-primary-foreground shadow-md">
              M
            </span>
            <span>Mingalar BKK</span>
          </div>

          {/* Account Overview Navigation */}
          <div className="space-y-1">
            <p className="px-3 text-[10px] font-extrabold uppercase tracking-wider text-muted-foreground">
              Account Overview
            </p>
            {userNavItems.map((item) => {
              const Icon = item.icon;
              const isActive = pathname === item.href;
              return (
                <Link
                  key={item.href}
                  href={item.href}
                  onClick={() => setSidebarOpen(false)}
                  className={`flex items-center gap-2.5 rounded-2xl px-3 py-2 text-xs font-bold transition-all ${
                    isActive
                      ? "bg-primary text-primary-foreground shadow-sm"
                      : "text-muted-foreground hover:bg-muted hover:text-foreground"
                  }`}
                >
                  <Icon className="h-4 w-4" />
                  {item.label}
                </Link>
              );
            })}
          </div>

          {/* All Services Navigation */}
          <div className="space-y-1 pt-2 border-t border-border/60">
            <p className="px-3 text-[10px] font-extrabold uppercase tracking-wider text-muted-foreground">
              All Services
            </p>
            {serviceNavItems.map((item) => {
              const Icon = item.icon;
              const isActive = pathname === item.href;
              return (
                <Link
                  key={item.href}
                  href={item.href}
                  onClick={() => setSidebarOpen(false)}
                  className={`flex items-center gap-2.5 rounded-2xl px-3 py-2 text-xs font-bold transition-all ${
                    isActive
                      ? "bg-primary/10 text-primary"
                      : "text-muted-foreground hover:bg-muted hover:text-foreground"
                  }`}
                >
                  <Icon className={`h-4 w-4 ${item.color}`} />
                  {item.label}
                </Link>
              );
            })}
          </div>
        </div>

        {/* Sidebar Footer: Log Out & Return to Main Web */}
        <div className="pt-4 border-t border-border/60 space-y-2">
          <Button
            onClick={handleLogout}
            disabled={isLoggingOut}
            variant="outline"
            size="sm"
            className="w-full justify-start rounded-2xl text-xs font-bold text-rose-500 border-rose-500/20 hover:bg-rose-500/10 hover:text-rose-600"
          >
            <LogOut className="mr-2 h-4 w-4" />
            {isLoggingOut ? "Logging out..." : "Log Out"}
          </Button>

          <Link href="/" className="block">
            <Button
              variant="ghost"
              size="sm"
              className="w-full justify-start rounded-2xl text-xs font-semibold text-muted-foreground"
            >
              <ArrowLeft className="mr-2 h-3.5 w-3.5" /> Back to Main Web
            </Button>
          </Link>
        </div>
      </aside>

      {/* Main Protected Content Area */}
      <main className="flex-1 p-4 md:p-8 overflow-y-auto">
        <div className="mx-auto max-w-6xl">{children}</div>
      </main>
    </div>
  );
}

"use client";

import { useState } from "react";
import Link from "next/link";
import {
  ArrowLeft,
  Bookmark,
  Briefcase,
  Building2,
  Calendar,
  ,
  Trash2,
  MapPin,
  ,
   } from "lucide-react";
import { toast } from "sonner";

import { AnimatedPage } from "@/components/ui/AnimatedPage";
import { Button } from "@/components/ui/button";

const mockSavedJobs = [
  {
    id: "job-1",
    title: "Bilingual Supervisor (Thai-Burmese)",
    company: "Mahachai Seafood Co., Ltd.",
    location: "Samut Sakhon",
    salary: "฿18,000 - ฿22,000 / month" },
  {
    id: "job-2",
    title: "Warehouse Staff & Logistic Support",
    company: "Bangkok Logistics Express",
    location: "Bang Na, Bangkok",
    salary: "฿15,000 - ฿17,000 / month" },
];

const mockSavedHousing = [
  {
    id: "house-1",
    title: "Charming Studio Apartment near BTS On Nut",
    location: "Sukhumvit 77, Bangkok",
    price: "฿4,500 / month" },
];

const mockSavedEvents = [
  {
    id: "evt-1",
    title: "Thingyan Water Festival Celebration 2026",
    date: "Sun, 12 Apr 2026",
    location: "Bangkok Cultural Center" },
];

export default function SavedPage() {
  const [activeTab, setActiveTab] = useState<"jobs" | "housing" | "events">("jobs");
  const [savedJobs, setSavedJobs] = useState(mockSavedJobs);
  const [savedHousing, setSavedHousing] = useState(mockSavedHousing);
  const [savedEvents, setSavedEvents] = useState(mockSavedEvents);

  const removeItem = (type: "jobs" | "housing" | "events", id: string) => {
    if (type === "jobs") {
      setSavedJobs(savedJobs.filter((item) => item.id !== id));
    } else if (type === "housing") {
      setSavedHousing(savedHousing.filter((item) => item.id !== id));
    } else if (type === "events") {
      setSavedEvents(savedEvents.filter((item) => item.id !== id));
    }
    toast.success("Item removed from saved list");
  };

  return (
    <AnimatedPage>
      <div className="min-h-screen bg-background py-8">
        <div className="container mx-auto px-6 max-w-5xl space-y-6">
          <Link
            href="/dashboard"
            className="inline-flex items-center text-xs text-muted-foreground hover:text-primary transition-colors"
          >
            <ArrowLeft className="mr-1.5 h-3.5 w-3.5" /> Back to Dashboard
          </Link>

          {/* Header Banner */}
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-border/60 pb-6">
            <div>
              <div className="flex items-center gap-2">
                <div className="flex h-10 w-10 items-center justify-center rounded-2xl bg-primary/10 text-primary">
                  <Bookmark className="h-5 w-5" />
                </div>
                <h1 className="text-2xl font-black text-foreground">Saved Bookmarks</h1>
              </div>
              <p className="mt-1 text-xs text-muted-foreground">
                Manage your saved jobs, housing listings, and upcoming community events in one
                place.
              </p>
            </div>
          </div>

          {/* Filter Tabs */}
          <div className="flex gap-2 border-b border-border/60 pb-3">
            <button
              type="button"
              onClick={() => setActiveTab("jobs")}
              className={`flex items-center gap-1.5 rounded-full px-4 py-2 text-xs font-bold transition-all ${
                activeTab === "jobs"
                  ? "bg-primary text-primary-foreground shadow-sm"
                  : "bg-muted/40 text-muted-foreground hover:bg-muted hover:text-foreground"
              }`}
            >
              <Briefcase className="h-3.5 w-3.5" /> Jobs ({savedJobs.length})
            </button>

            <button
              type="button"
              onClick={() => setActiveTab("housing")}
              className={`flex items-center gap-1.5 rounded-full px-4 py-2 text-xs font-bold transition-all ${
                activeTab === "housing"
                  ? "bg-primary text-primary-foreground shadow-sm"
                  : "bg-muted/40 text-muted-foreground hover:bg-muted hover:text-foreground"
              }`}
            >
              <Building2 className="h-3.5 w-3.5" /> Housing ({savedHousing.length})
            </button>

            <button
              type="button"
              onClick={() => setActiveTab("events")}
              className={`flex items-center gap-1.5 rounded-full px-4 py-2 text-xs font-bold transition-all ${
                activeTab === "events"
                  ? "bg-primary text-primary-foreground shadow-sm"
                  : "bg-muted/40 text-muted-foreground hover:bg-muted hover:text-foreground"
              }`}
            >
              <Calendar className="h-3.5 w-3.5" /> Events ({savedEvents.length})
            </button>
          </div>

          {/* Saved Tab Content */}
          <div className="space-y-4 pt-2">
            {/* Jobs Tab */}
            {activeTab === "jobs" &&
              (savedJobs.length > 0 ? (
                <div className="grid gap-4 sm:grid-cols-2">
                  {savedJobs.map((job) => (
                    <div
                      key={job.id}
                      className="rounded-3xl border border-border/80 bg-card p-5 shadow-sm space-y-3 flex flex-col justify-between"
                    >
                      <div>
                        <span className="text-[10px] font-bold text-primary bg-primary/10 px-2.5 py-0.5 rounded-full">
                          {job.salary}
                        </span>
                        <h3 className="mt-2 text-base font-bold text-foreground">{job.title}</h3>
                        <p className="text-xs text-muted-foreground mt-0.5">{job.company}</p>
                        <div className="flex items-center gap-1 text-xs text-muted-foreground mt-2">
                          <MapPin className="h-3.5 w-3.5 text-primary shrink-0" />
                          <span>{job.location}</span>
                        </div>
                      </div>

                      <div className="flex items-center gap-2 pt-3 border-t border-border/40">
                        <Link href="/jobs" className="flex-1">
                          <Button size="sm" className="w-full rounded-xl text-xs font-semibold">
                            Apply Now
                          </Button>
                        </Link>
                        <Button
                          type="button"
                          variant="ghost"
                          size="sm"
                          onClick={() => removeItem("jobs", job.id)}
                          className="rounded-xl p-2 text-muted-foreground hover:text-rose-500 hover:bg-rose-500/10"
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <EmptyState label="No saved jobs found." href="/jobs" buttonText="Browse Jobs" />
              ))}

            {/* Housing Tab */}
            {activeTab === "housing" &&
              (savedHousing.length > 0 ? (
                <div className="grid gap-4 sm:grid-cols-2">
                  {savedHousing.map((house) => (
                    <div
                      key={house.id}
                      className="rounded-3xl border border-border/80 bg-card p-5 shadow-sm space-y-3 flex flex-col justify-between"
                    >
                      <div>
                        <span className="text-[10px] font-bold text-sky-600 bg-sky-500/10 px-2.5 py-0.5 rounded-full">
                          {house.price}
                        </span>
                        <h3 className="mt-2 text-base font-bold text-foreground">{house.title}</h3>
                        <div className="flex items-center gap-1 text-xs text-muted-foreground mt-2">
                          <MapPin className="h-3.5 w-3.5 text-sky-600 shrink-0" />
                          <span>{house.location}</span>
                        </div>
                      </div>

                      <div className="flex items-center gap-2 pt-3 border-t border-border/40">
                        <Link href="/housing" className="flex-1">
                          <Button
                            size="sm"
                            className="w-full rounded-xl text-xs font-semibold bg-sky-600 hover:bg-sky-700 text-white"
                          >
                            View Listing
                          </Button>
                        </Link>
                        <Button
                          type="button"
                          variant="ghost"
                          size="sm"
                          onClick={() => removeItem("housing", house.id)}
                          className="rounded-xl p-2 text-muted-foreground hover:text-rose-500 hover:bg-rose-500/10"
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <EmptyState
                  label="No saved housing listings found."
                  href="/housing"
                  buttonText="Browse Housing"
                />
              ))}

            {/* Events Tab */}
            {activeTab === "events" &&
              (savedEvents.length > 0 ? (
                <div className="grid gap-4 sm:grid-cols-2">
                  {savedEvents.map((evt) => (
                    <div
                      key={evt.id}
                      className="rounded-3xl border border-border/80 bg-card p-5 shadow-sm space-y-3 flex flex-col justify-between"
                    >
                      <div>
