"use client";

import { useCallback, useEffect, useState } from "react";
import { ChevronLeft, ChevronRight, X } from "lucide-react";

export interface Photo {
  id: string;
  url: string;
  alt: string;
}

export interface PhotoLightboxProps {
  isOpen: boolean;
  photos: Photo[];
  initialIndex: number;
  onClose: () => void;
}

export function PhotoLightbox({ isOpen, photos, initialIndex, onClose }: PhotoLightboxProps) {
  const [currentIndex, setCurrentIndex] = useState(initialIndex);

  const goToPrevious = useCallback(() => {
    setCurrentIndex((prev) => (prev === 0 ? photos.length - 1 : prev - 1));
  }, [photos.length]);

  const goToNext = useCallback(() => {
    setCurrentIndex((prev) => (prev === photos.length - 1 ? 0 : prev + 1));
  }, [photos.length]);

  useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
      if (e.key === "ArrowLeft") goToPrevious();
      if (e.key === "ArrowRight") goToNext();
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, onClose, goToPrevious, goToNext]);

  if (!isOpen) return null;

  const currentPhoto = photos[currentIndex];

  return (
    <div className="fixed inset-0 z-50 bg-black/90 flex items-center justify-center">
      <div className="relative w-full h-full flex items-center justify-center">
        <button
          onClick={onClose}
          className="absolute top-4 right-4 z-10 bg-white/20 hover:bg-white/30 text-white p-2 rounded-full transition-colors"
          aria-label="Close lightbox"
        >
          <X className="h-6 w-6" />
        </button>

        <div className="relative w-full max-w-4xl mx-auto px-4">
          <img
            src={currentPhoto.url}
            alt={currentPhoto.alt}
            className="w-full h-auto max-h-[80vh] object-contain"
          />

          {photos.length > 1 && (
            <>
              <button
                onClick={goToPrevious}
                className="absolute left-0 top-1/2 -translate-y-1/2 bg-white/20 hover:bg-white/30 text-white p-3 rounded-r-lg transition-colors"
                aria-label="Previous photo"
              >
                <ChevronLeft className="h-6 w-6" />
              </button>

              <button
                onClick={goToNext}
                className="absolute right-0 top-1/2 -translate-y-1/2 bg-white/20 hover:bg-white/30 text-white p-3 rounded-l-lg transition-colors"
                aria-label="Next photo"
              >
                <ChevronRight className="h-6 w-6" />
              </button>

              <div className="absolute bottom-4 left-1/2 -translate-x-1/2 bg-black/50 text-white text-sm px-4 py-2 rounded-full">
                {currentIndex + 1} / {photos.length}
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

'use client'

import { Card, Badge } from '@/components/ui'
import { Button } from '@/components/ui/button-variants'
import { Star, , Heart, Share2 } from 'lucide-react'
import { useState } from 'react'

export interface Business {
  id: string
  name: string
  category: string
  image: string
  logo: string
  rating: number
  reviewCount: number
  address: string
  distance: number
  isOpen: boolean
  isVerified: boolean
  isSaved?: boolean
}

interface BusinessListViewProps {
  businesses: Business[]
  onSave?: (id: string) => void
  onShare?: (id: string) => void
}

export function BusinessListView({
  businesses,
  onSave,
  onShare }: BusinessListViewProps) {
  const [savedItems, setSavedItems] = useState<Set<string>>(
    new Set(businesses.filter((b) => b.isSaved).map((b) => b.id))
  )

  const handleSave = (id: string) => {
    const newSaved = new Set(savedItems)
    if (newSaved.has(id)) {
      newSaved.delete(id)
    } else {
      newSaved.add(id)
    }
    setSavedItems(newSaved)
    onSave?.(id)
  }

  return (
    <div className="space-y-4">
      {businesses.map((business) => (
        <Card key={business.id} interactive className="overflow-hidden">
          <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
            {/* Image & Basic Info */}
            <div className="flex gap-4 flex-1">
              {/* Logo */}
              <div className="flex-shrink-0">
                <img
                  src={business.logo}
                  alt={business.name}
                  className="h-16 w-16 rounded-lg object-cover"
                />
              </div>

              {/* Details */}
              <div className="flex-1">
                <div className="flex items-center gap-2 mb-1">
                  <h3 className="font-semibold text-foreground">{business.name}</h3>
                  {business.isVerified && (
                    <svg
                      className="h-4 w-4 text-primary"
                      fill="currentColor"
                      viewBox="0 0 20 20"
                    >
                      <path
                        fillRule="evenodd"
                        d="M6.267 3.455a3.066 3.066 0 001.745-.723 3.066 3.066 0 013.976 0 3.066 3.066 0 001.745.723 3.066 3.066 0 012.812 2.812c.051.643.304 1.254.723 1.745a3.066 3.066 0 010 3.976 3.066 3.066 0 00-.723 1.745 3.066 3.066 0 01-2.812 2.812 3.066 3.066 0 00-1.745.723 3.066 3.066 0 01-3.976 0 3.066 3.066 0 00-1.745-.723 3.066 3.066 0 01-2.812-2.812 3.066 3.066 0 00-.723-1.745 3.066 3.066 0 010-3.976 3.066 3.066 0 00.723-1.745 3.066 3.066 0 012.812-2.812zm7.44 5.252a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z"
                        clipRule="evenodd"
                      />
                    </svg>
                  )}
                  <Badge size="sm" variant="secondary">
                    {business.category}
                  </Badge>
                </div>

                <p className="text-xs text-muted-foreground mb-2">{business.address}</p>

                <div className="flex flex-wrap items-center gap-3">
                  {/* Rating */}
                  <div className="flex items-center gap-1">
                    {[...Array(5)].map((_, i) => (
                      <Star
                        key={i}
                        className={`h-3 w-3 ${
                          i < Math.floor(business.rating)
                            ? 'fill-secondary text-secondary'
                            : 'text-muted-foreground'
                        }`}
                      />
                    ))}
                    <span className="text-xs font-medium text-foreground ml-1">
                      {business.rating} ({business.reviewCount})
                    </span>
                  </div>

                  {/* Distance */}
                  <span className="text-xs text-muted-foreground">
                    {business.distance} km away
                  </span>

                  {/* Status */}
                  <Badge
                    size="sm"
                    variant={business.isOpen ? 'success' : 'danger'}
                    className="text-xs"
                  >
                    {business.isOpen ? 'Open' : 'Closed'}
                  </Badge>
                </div>
              </div>
            </div>

            {/* Actions */}
            <div className="flex gap-2 md:flex-col md:items-end">
              <Button
                size="sm"
                variant="ghost"
                icon={
                  <Heart
                    className="h-4 w-4"
                    fill={savedItems.has(business.id) ? 'currentColor' : 'none'}
                  />
                }
                onClick={() => handleSave(business.id)}
              />
              <Button
                size="sm"
                variant="ghost"
                icon={<Share2 className="h-4 w-4" />}
                onClick={() => onShare?.(business.id)}
              />
            </div>
          </div>
        </Card>
      ))}
    </div>
  )
}

'use client'

import { useState } from 'react'
import { Card } from '@/components/ui'
import { ChevronDown } from 'lucide-react'

interface FilterOption {
  id: string
  label: string
  value: string
}

interface FilterPanelProps {
  onRatingChange?: (rating: number) => void
  onDistanceChange?: (distance: number) => void
  onStatusChange?: (status: 'open' | 'all') => void
}

export function FilterPanel({
  onRatingChange,
  onDistanceChange,
  onStatusChange,
}: FilterPanelProps) {
  const [expandedSections, setExpandedSections] = useState<Record<string, boolean>>({
    rating: true,
    distance: true,
    status: true,
  })

  const toggleSection = (section: string) => {
    setExpandedSections((prev) => ({
      ...prev,
      [section]: !prev[section],
    }))
  }

  return (
    <div className="space-y-4">
      {/* Rating Filter */}
      <Card>
        <button
          onClick={() => toggleSection('rating')}
          className="flex w-full items-center justify-between text-foreground"
        >
          <h4 className="font-semibold">Rating</h4>
          <ChevronDown
            className={`h-4 w-4 transition-transform ${expandedSections.rating ? '' : '-rotate-90'}`}
          />
        </button>

        {expandedSections.rating && (
          <div className="mt-4 space-y-3">
            {[5, 4, 3, 2].map((rating) => (
              <label key={rating} className="flex cursor-pointer items-center gap-2">
                <input
                  type="radio"
                  name="rating"
                  value={rating}
                  onChange={(e) => onRatingChange?.(Number(e.target.value))}
                  className="h-4 w-4"
                />
                <span className="text-sm text-foreground">
                  {rating}★ & Up
                </span>
              </label>
            ))}
          </div>
        )}
      </Card>

      {/* Distance Filter */}
      <Card>
        <button
          onClick={() => toggleSection('distance')}
          className="flex w-full items-center justify-between text-foreground"
        >
          <h4 className="font-semibold">Distance</h4>
          <ChevronDown
            className={`h-4 w-4 transition-transform ${expandedSections.distance ? '' : '-rotate-90'}`}
          />
        </button>

        {expandedSections.distance && (
          <div className="mt-4 space-y-3">
            {[
              { label: 'Within 1 km', value: 1 },
              { label: 'Within 5 km', value: 5 },
              { label: 'Within 10 km', value: 10 },
              { label: 'Within 25 km', value: 25 },
            ].map((option) => (
              <label key={option.value} className="flex cursor-pointer items-center gap-2">
                <input
                  type="radio"
                  name="distance"
                  value={option.value}
                  onChange={(e) => onDistanceChange?.(Number(e.target.value))}
                  className="h-4 w-4"
                />
                <span className="text-sm text-foreground">{option.label}</span>
              </label>
            ))}
          </div>
        )}
      </Card>

      {/* Status Filter */}
      <Card>
        <button
          onClick={() => toggleSection('status')}
          className="flex w-full items-center justify-between text-foreground"
        >
          <h4 className="font-semibold">Open Now</h4>
          <ChevronDown
            className={`h-4 w-4 transition-transform ${expandedSections.status ? '' : '-rotate-90'}`}
          />
        </button>

        {expandedSections.status && (
          <div className="mt-4 space-y-3">
            <label className="flex cursor-pointer items-center gap-2">
              <input
                type="radio"
                name="status"
                value="open"
                onChange={(e) => onStatusChange?.(e.target.value as 'open' | 'all')}
                className="h-4 w-4"
              />
              <span className="text-sm text-foreground">Open Now</span>
            </label>
            <label className="flex cursor-pointer items-center gap-2">
              <input
                type="radio"
                name="status"
                value="all"
                defaultChecked
                onChange={(e) => onStatusChange?.(e.target.value as 'open' | 'all')}
                className="h-4 w-4"
              />
              <span className="text-sm text-foreground">All Businesses</span>
            </label>
          </div>
        )}
      </Card>
    </div>
  )
}

"use client";

import Image from "next/image";
