              {/* Search Button */}
              <Button
                type="submit"
                size="lg"
                onClick={handleSearchClick}
                className="rounded-xl px-6 md:px-8 hover:shadow-lg transition-all duration-300"
              >
                <Search className="h-5 w-5" />
                <span className="hidden md:inline">Search</span>
              </Button>
            </div>

            {/* AI Badge */}
            <div className="mt-3 flex items-center gap-2 px-4">
              <Sparkles className="h-4 w-4 text-secondary" />
              <span className="text-xs font-semibold text-secondary">AI-Powered Search</span>
            </div>
          </div>

          {/* Quick Tags */}
          <div className="text-center">
            <p className="text-sm text-muted-foreground mb-4">Popular searches:</p>
            <div className="flex flex-wrap justify-center gap-3">
              {[
                'IT Jobs Bangkok',
                'House Rent',
                'Myanmar Restaurant',
                'Thai Language Class',
                'Community Events',
              ].map((tag, i) => (
                <motion.button
                  key={i}
                  onClick={() => setQuery(tag)}
                  className="px-4 py-2 rounded-full bg-card border border-border text-sm font-medium text-foreground hover:bg-secondary/10 hover:border-secondary transition-colors"
                  whileHover={{ scale: 1.05 }}
                  transition={{ type: 'spring', stiffness: 300 }}
                >
                  {tag}
                </motion.button>
              ))}
            </div>
          </div>
        </motion.form>


      </Container>
    </section>
  )
}

import { cn } from '@/lib/utils'

interface AvatarProps {
  src?: string
  alt: string
  fallback: string
  size?: 'sm' | 'md' | 'lg' | 'xl'
  className?: string
}

export function Avatar({ src, alt, fallback, size = 'md', className }: AvatarProps) {
  const sizeClasses = {
    sm: 'h-8 w-8 text-xs',
    md: 'h-10 w-10 text-sm',
    lg: 'h-12 w-12 text-base',
    xl: 'h-16 w-16 text-lg',
  }

  return (
    <div
      className={cn(
        'flex items-center justify-center rounded-full bg-muted font-semibold text-muted-foreground',
        sizeClasses[size],
        className,
      )}
    >
      {src ? (
        <img src={src} alt={alt} className="h-full w-full rounded-full object-cover" />
      ) : (
        <span>{fallback}</span>
      )}
    </div>
  )
}
